// 사운드 효과를 위한 AudioContext 생성
const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();

// 테트리스 스타일의 사운드 생성 함수
function createTetrisSound(type: 'move' | 'rotate' | 'drop' | 'clear' | 'gameOver') {
  const oscillator = audioContext.createOscillator();
  const gainNode = audioContext.createGain();

  oscillator.connect(gainNode);
  gainNode.connect(audioContext.destination);

  switch (type) {
    case 'move':
      // 짧은 높은 음의 비프음
      oscillator.type = 'square';
      oscillator.frequency.value = 880; // A5
      gainNode.gain.setValueAtTime(0, audioContext.currentTime);
      gainNode.gain.linearRampToValueAtTime(0.2, audioContext.currentTime + 0.01);
      gainNode.gain.linearRampToValueAtTime(0, audioContext.currentTime + 0.08);
      oscillator.start(audioContext.currentTime);
      oscillator.stop(audioContext.currentTime + 0.08);
      break;

    case 'rotate':
      // 회전음 (약간 더 낮은 음)
      oscillator.type = 'square';
      oscillator.frequency.value = 783.99; // G5
      gainNode.gain.setValueAtTime(0, audioContext.currentTime);
      gainNode.gain.linearRampToValueAtTime(0.2, audioContext.currentTime + 0.01);
      gainNode.gain.linearRampToValueAtTime(0, audioContext.currentTime + 0.08);
      oscillator.start(audioContext.currentTime);
      oscillator.stop(audioContext.currentTime + 0.08);
      break;

    case 'drop':
      // 낙하음 (낮은 음에서 시작)
      oscillator.type = 'square';
      oscillator.frequency.setValueAtTime(440, audioContext.currentTime); // A4
      oscillator.frequency.linearRampToValueAtTime(110, audioContext.currentTime + 0.15); // A2
      gainNode.gain.setValueAtTime(0.3, audioContext.currentTime);
      gainNode.gain.linearRampToValueAtTime(0, audioContext.currentTime + 0.15);
      oscillator.start(audioContext.currentTime);
      oscillator.stop(audioContext.currentTime + 0.15);
      break;

    case 'clear':
      // 라인 제거음 (폭발음 효과)
      oscillator.type = 'sawtooth';
      oscillator.frequency.setValueAtTime(880, audioContext.currentTime); // A5
      oscillator.frequency.exponentialRampToValueAtTime(110, audioContext.currentTime + 0.2); // A2
      gainNode.gain.setValueAtTime(0, audioContext.currentTime);
      gainNode.gain.linearRampToValueAtTime(0.3, audioContext.currentTime + 0.01);
      gainNode.gain.linearRampToValueAtTime(0, audioContext.currentTime + 0.2);

      // 노이즈 추가 (폭발음 효과)
      const noiseLength = 8820;
      const noiseBuffer = audioContext.createBuffer(1, noiseLength, audioContext.sampleRate);
      const noiseData = noiseBuffer.getChannelData(0);
      for (let i = 0; i < noiseLength; i++) {
        noiseData[i] = Math.random() * 2 - 1;
      }

      const noiseNode = audioContext.createBufferSource();
      const noiseGain = audioContext.createGain();
      noiseNode.buffer = noiseBuffer;
      noiseNode.connect(noiseGain);
      noiseGain.connect(audioContext.destination);
      noiseGain.gain.setValueAtTime(0.3, audioContext.currentTime);
      noiseGain.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + 0.2);

      noiseNode.start(audioContext.currentTime);
      oscillator.start(audioContext.currentTime);
      oscillator.stop(audioContext.currentTime + 0.2);
      break;

    case 'gameOver':
      // 게임오버 음 (하강하는 시퀀스)
      oscillator.type = 'square';
      const startFreq = 880; // A5
      const duration = 1.5;
      const steps = 8;

      for (let i = 0; i < steps; i++) {
        const time = audioContext.currentTime + (i * duration / steps);
        oscillator.frequency.setValueAtTime(startFreq / Math.pow(2, i/2), time);
        gainNode.gain.setValueAtTime(0.3, time);
        gainNode.gain.linearRampToValueAtTime(0, time + duration / steps - 0.01);
      }

      oscillator.start(audioContext.currentTime);
      oscillator.stop(audioContext.currentTime + duration);
      break;
  }
}

export const sounds = {
  move: () => createTetrisSound('move'),
  rotate: () => createTetrisSound('rotate'),
  drop: () => createTetrisSound('drop'),
  clear: () => createTetrisSound('clear'),
  gameOver: () => createTetrisSound('gameOver')
};
